# heart_rate_monitor_rpi.py
# Reads heart-rate and SpO2 data from a MAX30102 sensor on a Raspberry Pi.
# Logs the data with timestamps and prints it to the console.

import time
import board
import busio
import adafruit_max30102

# Configuration
LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1  # seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the MAX30102 sensor."""
    try:
        sensor = adafruit_max30102.MAX30102(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing MAX30102 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads IR and RED ADC samples from the sensor."""
    try:
        return sensor.read_samples('ir'), sensor.read_samples('red')
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def estimate_heart_rate(ir_samples, red_samples):
    """Estimates heart rate from IR and RED samples."""
    if ir_samples is None or red_samples is None:
        return None

    combined_samples = [(ir - red) for ir, red in zip(ir_samples, red_samples) if ir is not None and red is not None]

    if not combined_samples:
        return None

    peak_count = sum(1 for sample in combined_samples if sample > 1000) # Threshold for peak detection
    if peak_count > 0:
        return 60 / (combined_samples.index(max(combined_samples)) * 0.004) # Estimate BPM
    else:
        return None

def log_data(log_file, timestamp, heart_rate, spo2):
    """Logs the heart rate and SpO2 data to a file."""
    try:
        with open(log_file, "a") as file:
            file.write(f"{timestamp},{heart_rate},{spo2}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def print_data(heart_rate, spo2):
    """Prints the heart rate and SpO2 data to the console."""
    if heart_rate is not None:
        print(f"Heart Rate: {heart_rate} BPM")
    if spo2 is not None:
        print(f"SpO2: {spo2} %")

def main():
    """Main function to read and process sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            ir_samples, red_samples = read_sensor_data(sensor)
            heart_rate = estimate_heart_rate(ir_samples, red_samples)
            spo2 = sensor.get_spo2() if sensor else None # Spo2 requires sensor object

            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            log_data(LOG_FILE, timestamp, heart_rate, spo2)
            print_data(heart_rate, spo2)

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for adafruit_max30102 or busio.I2C
        print("Program finished.")

if __name__ == "__main__":
    main()

