#!/usr/bin/env python3

import time
import datetime
import logging
import sqlite3
import board
import busio
import adafruit_bmp280
import adafruit_bme280
import adafruit_ms8607
import configparser
import os
import signal
import sys

# Configuration file path
CONFIG_FILE = "config.txt"
ERROR_LOG = "error.log"

# Configure logging
logging.basicConfig(filename=ERROR_LOG, level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Global variable to track program running state
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C signal to gracefully exit the program."""
    global running
    logging.info("Program exiting gracefully...")
    running = False
    sys.exit(0)

def load_configuration(config_file):
    """Loads configuration from the specified file."""
    config = configparser.ConfigParser()
    try:
        config.read(config_file)
        return config
    except Exception as e:
        logging.error(f"Error loading configuration file: {e}")
        return None

def detect_sensors():
    """Detects the presence of BMP280, BME280, and MS8607 sensors on the I2C bus."""
    sensors = {}
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # BMP280 can be at address 0x76 or 0x77
        if i2c.try_lock():
            try:
                # Attempt to read the chip ID register (0xD0) to verify the sensor
                bmp280 = adafruit_bmp280.BMP280_I2C(i2c)
                sensors["BMP280"] = {"address": 0x76, "id": "BMP280"}
                logging.info("BMP280 sensor detected at address 0x%x", sensors["BMP280"]["address"])
            except Exception as e:
                logging.warning(f"BMP280 sensor not responding at address 0x%x: {e}", sensors["BMP280"]["address"])
            finally:
                i2c.unlock()
        else:
            logging.warning("I2C bus not available")

        # BME280 can be at address 0x76 or 0x77
        if i2c.try_lock():
            try:
                # Attempt to read the chip ID register (0xD0) to verify the sensor
                bme280 = adafruit_bme280.BME280_I2C(i2c)
                sensors["BME280"] = {"address": 0x76, "id": "BME280"}
                logging.info("BME280 sensor detected at address 0x%x", sensors["BME280"]["address"])
            except Exception as e:
                logging.warning(f"BME280 sensor not responding at address 0x%x: {e}", sensors["BME280"]["address"])
            finally:
                i2c.unlock()
        else:
            logging.warning("I2C bus not available")

        # MS8607 can be at address 0x78
        if i2c.try_lock():
            try:
                # Attempt to read the chip ID register (0xD0) to verify the sensor
                ms8607 = adafruit_ms8607.MS8607(i2c)
                sensors["MS8607"] = {"address": 0x78, "id": "MS8607"}
                logging.info("MS8607 sensor detected at address 0x%x", sensors["MS8607"]["address"])
            except Exception as e:
                logging.warning(f"MS8607 sensor not responding at address 0x%x: {e}", sensors["MS8607"]["address"])
            finally:
                i2c.unlock()
        else:
            logging.warning("I2C bus not available")

    except Exception as e:
        logging.error(f"Error detecting sensors: {e}")
    return sensors

def initialize_sensors(config, sensors):
    """Initializes the sensors based on the configuration file."""
    sensor_instances = {}
    for sensor_type, sensor_data in config.items():
        if sensor_type.startswith("Sensor"):
            sensor_id = sensor_data.get("ID")
            sensor_address = int(sensor_data.get("Address"), 16)
            sensor_type_name = sensor_data.get("Type")
            if sensor_type_name in sensors and sensor_id in sensors[sensor_type_name]["id"]:
                try:
                    if sensor_type_name == "BMP280":
                        sensor_instances[sensor_id] = adafruit_bmp280.BMP280_I2C(busio.I2C(board.SCL, board.SDA), address=sensor_address)
                    elif sensor_type_name == "BME280":
                        sensor_instances[sensor_id] = adafruit_bme280.BME280_I2C(busio.I2C(board.SCL, board.SDA), address=sensor_address)
                    elif sensor_type_name == "MS8607":
                        sensor_instances[sensor_id] = adafruit_ms8607.MS8607(busio.I2C(board.SCL, board.SDA), address=sensor_address)
                    logging.info(f"Sensor {sensor_id} ({sensor_type_name}) initialized at address 0x{x:02x}")
                except Exception as e:
                    logging.error(f"Failed to initialize sensor {sensor_id} ({sensor_type_name}): {e}")
                    sensor_instances[sensor_id] = None
            else:
                logging.warning(f"Sensor {sensor_id} ({sensor_type_name}) not found in sensor detection.")
                sensor_instances[sensor_id] = None
    return sensor_instances

def read_sensor_data(sensor, sensor_id):
    """Reads pressure, temperature, and humidity data from the sensor."""
    if sensor is None:
        return None, None, None

    try:
        if sensor_type_name == "BMP280":
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = None
        elif sensor_type_name == "BME280":
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.humidity
        elif sensor_type_name == "MS8607":
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.relative_humidity
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading sensor {sensor_id}: {e}")
        return None, None, None

def validate_data(pressure, temperature, humidity):
    """Validates the sensor data against reasonable ranges."""
    if pressure is None or not (70000 <= pressure <= 110000):
        return False
    if temperature is None or not (-20 <= temperature <= 50):
        return False
    if humidity is not None and not (0 <= humidity <= 100):
        return False
    return True

def store_data(db_conn, timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    """Stores the sensor data in the SQLite database."""
    try:
        cursor = db_conn.cursor()
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    """Main function to run the environmental sensor monitoring program."""
    global running

    # Load configuration
    config = load_configuration(CONFIG_FILE)
    if config is None:
        print("Failed to load configuration. Exiting.")
        sys.exit(1)

    # Detect sensors
    sensors = detect_sensors()
    if not sensors:
        print("No sensors detected. Exiting.")
        sys.exit(0)

    # Initialize sensors based on configuration
    sensor_instances = initialize_sensors(config, sensors)
    if not sensor_instances:
        print("Failed to initialize sensors. Exiting.")
        sys.exit(1)

    # Database setup
    db_conn = None
    try:
        db_conn = sqlite3.connect("wildlife_data.db")
        cursor = db_conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        db_conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
        print("Failed to connect to database. Exiting.")
        sys.exit(1)

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    # Main loop
    sampling_interval = int(config["Sampling"]["Sampling_Interval_Seconds"])
    while running:
        for sensor_id, sensor in sensor_instances.items():
            sensor_type_name = None
            for sensor_type, sensor_data in config.items():
                if sensor_data.get("ID") == sensor_id:
                    sensor_type_name = sensor_type
                    break

            if sensor_type_name:
                pressure, temperature, humidity = read_sensor_data(sensor, sensor_id)
                if pressure is not None and temperature is not None:
                    if validate_data(pressure, temperature, humidity):
                        timestamp = datetime.datetime.now().isoformat()
                        store_data(db_conn, timestamp, sensor_type_name, sensor_id, pressure, temperature, humidity)
                        print(f"{timestamp} - {sensor_type_name} {sensor_id}: Pressure={pressure:.2f} Pa, Temperature={temperature:.2f} °C")
                    else:
                        logging.warning(f"Invalid data from {sensor_type_name} {sensor_id}: Pressure={pressure:.2f} Pa, Temperature={temperature:.2f} °C")
                else:
                    logging.warning(f"Failed to read data from {sensor_type_name} {sensor_id}")
            else:
                logging.warning(f"Sensor {sensor_id} not found in configuration.")

        time.sleep(sampling_interval)

    # Clean up resources
    if db_conn:
        db_conn.close()
    logging.info("Program finished.")

if __name__ == "__main__":
    main()

