import multiprocessing
import os
import signal
import time
import atexit
import threading
from datetime import datetime

from setproctitle import setproctitle

import config
import logsupport as L
from controlevents import CEvent, PostEvent, ConsoleEvent

# Constants
FAILSAFE_INTERVAL_SECONDS = 60
KEEP_ALIVE_CHECK_INTERVAL_SECONDS = FAILSAFE_INTERVAL_SECONDS / 2
TOMBSTONE_FILE = '/home/pi/.tombstoneW'

# Global Event
keep_alive_event = multiprocessing.Event()

# Ensure the necessary directories exist
os.makedirs('/home/pi/Console/.HistoryBuffer', exist_ok=True)


def log_debug(message):
    """Logs debug messages with timestamp to a file and prints to console."""
    try:
        with open('/home/pi/Console/.HistoryBuffer/hlogW', 'a') as debug_file:
            debug_file.write(f'{datetime.now()} - {message}\n')
            debug_file.flush()
    except Exception as e:
