import speech_recognition as sr
import picamera2
import RPi.GPIO as GPIO
import time
import datetime
import os
import signal
import sys
import random
import adafruit_dht

# Constants and Configuration
LIGHT_PIN = 17  # GPIO pin for the lights
DHT_PIN = 4  # GPIO pin for the DHT11 sensor
WAKE_WORD = "Greenhouse"
SIMULATED_TEMPERATURE_MIN = 15
SIMULATED_TEMPERATURE_MAX = 35
CAMERA_RESOLUTION = (640, 480)

# Global variables for state management
lights_on = False
camera_enabled = True
dht_enabled = True

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"Error initializing GPIO: {e}. Falling back to simulated GPIO.")
    GPIO = None  # Disable GPIO if initialization fails

# Initialize DHT sensor
try:
    dht_device = adafruit_dht.DHT11(DHT_PIN)
    print("DHT sensor initialized successfully.")
except Exception as e:
    print(f"Error initializing DHT sensor: {e}. Falling back to simulated temperature readings.")
    dht_device = None
    dht_enabled = False

# Initialize Camera
try:
    camera = picamera2.PiCamera2()
    camera.configure({"size": CAMERA_RESOLUTION})
    camera.start()
    print("Camera initialized successfully.")
except Exception as e:
    print(f"Error initializing camera: {e}. Camera functionality disabled.")
    camera = None
    camera_enabled = False

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Shutting down gracefully...")
    if GPIO:
        GPIO.cleanup()
    if camera:
        camera.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to read temperature from DHT11 sensor
def read_temperature():
    if dht_enabled and dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT11 sensor returned None. Falling back to simulated temperature.")
                return None
        except RuntimeError as error:
            # Errors happen fairly often, DHT's are hard to read, just keep going
            print(error.args[0])
            return None
        except Exception as e:
            print(f"Error reading temperature: {e}. Falling back to simulated temperature.")
            return None
    else:
        # Simulate temperature if DHT is disabled
        return random.uniform(SIMULATED_TEMPERATURE_MIN, SIMULATED_TEMPERATURE_MAX)

# Function to capture an image
def capture_image():
    if camera_enabled and camera:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture_file(filename)
            print(f"Captured image: {filename}")
            return filename
        except Exception as e:
            print(f"Error capturing image: {e}")
            return None
    else:
        print("Camera is disabled or unavailable.")
        return None

# Function to turn the lights on
def turn_lights_on():
    global lights_on
    if GPIO:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            lights_on = True
            print("Lights turned ON.")
        except Exception as e:
            print(f"Error turning lights on: {e}.  Simulating lights on.")
    else:
        print("Simulating lights on.")
        lights_on = True

# Function to turn the lights off
def turn_lights_off():
    global lights_on
    if GPIO:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            lights_on = False
            print("Lights turned OFF.")
        except Exception as e:
            print(f"Error turning lights off: {e}. Simulating lights off.")
    else:
        print("Simulating lights off.")
        lights_on = False

# Function to process voice commands
def process_command(command):
    global lights_on
    command = command.lower()
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        temperature = read_temperature()
        if temperature is not None:
            print(f"The temperature is {temperature:.1f} degrees Celsius.")
        else:
            print("Could not read the temperature.")
    elif "take a picture" in command:
        image_file = capture_image()
        if image_file:
            print(f"Image saved as {image_file}")
        else:
            print("Failed to capture an image.")
    else:
        print("Unknown command.")

# Main program loop
def main():
    recognizer = sr.Recognizer()
    microphone = sr.Microphone()

    with microphone as source:
        recognizer.adjust_for_ambient_noise(source)  # Adjust for background noise

    print("Greenhouse control system started. Say 'Greenhouse' to start.")

    while True:
        try:
            with microphone as source:
                print("Say 'Greenhouse' to start...")
                audio = recognizer.listen(source, timeout=5) # Listen for 5 seconds

            try:
                # Voice recognition using Google Web Speech API
                recognized_text = recognizer.recognize_google(audio)
                print(f"You said: {recognized_text}")

                if "greenhouse" in recognized_text.lower():
                    print("Recognized wake word.")
                    try:
                        command = recognizer.recognize_google(audio)
                        process_command(command)
                    except sr.UnknownValueError:
                        print("Could not understand audio")
                    except sr.RequestError as e:
                        print(f"Could not request results from Google Speech Recognition service; {e}")
            except sr.UnknownValueError:
                print("Could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")

        except sr.WaitTimeoutError:
            print("No speech detected within timeout.")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

