import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Define sensor reading interval in seconds
READING_INTERVAL = 2

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
        return multiplexer
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_bme280(multiplexer):
    """Initialize the BME280 temperature and humidity sensor."""
    try:
        i2c_channel = multiplexer.channels[0]
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_channel)
        return bme280_sensor
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return None

def initialize_tsl2591(multiplexer):
    """Initialize the TSL2591 light sensor."""
    try:
        i2c_channel = multiplexer.channels[1]
        tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_channel)
        return tsl2591_sensor
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        return None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_sensor_data(temperature, humidity, light_intensity):
    """Display the sensor data in a user-friendly format."""
    if all(v is not None for v in [temperature, humidity, light_intensity]):
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")
    else:
        print("Failed to read sensor data.")

def main():
    """Main function to read and display sensor data in a loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READING_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for these libraries, but good practice to include a finally block
        pass

if __name__ == "__main__":
    main()

