# gpio_input_monitor.py
# A script to monitor digital input sensors on a Raspberry Pi.
# This version uses gpiozero for simplified sensor interaction.

import time
import signal
import sys
from gpiozero import DigitalInputDevice

# Define the GPIO pins connected to the sensors (BCM numbering)
SENSOR_PINS = [17, 27, 22]

# Define the poll interval in seconds
POLL_INTERVAL = 1

# Global list to hold sensor objects
sensor_list = []

def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGTERM signals for graceful exit."""
    print("\nExiting gracefully...")
    for sensor in sensor_list:
        sensor.close()  # Release GPIO resources
    sys.exit(0)

def initialize_sensors(pins):
    """Initializes the digital input sensors with pull-up resistors."""
    global sensor_list
    try:
        sensor_list = [DigitalInputDevice(pin, pull_up=True) for pin in pins]
        print(f"Sensors initialized on pins: {pins}")
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        sys.exit(1)

def monitor_sensors(sensor_list):
    """Monitors the sensors and prints responses based on input."""
    try:
        for sensor in sensor_list:
            if sensor.is_active:
                if sensor_list.index(sensor) == 0:
                    print('Response for sensor 1')
                elif sensor_list.index(sensor) == 1:
                    print('Response for sensor 2')
                elif sensor_list.index(sensor) == 2:
                    print('Response for sensor 3')
    except Exception as e:
        print(f"Error reading sensor data: {e}")

def main():
    """Main function to run the sensor monitoring loop."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_sensors(SENSOR_PINS)

    try:
        while True:
            monitor_sensors(sensor_list)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Cleaning up GPIO...")
        for sensor in sensor_list:
            sensor.close()
        print("Exiting.")

if __name__ == "__main__":
    main()

