import time
import requests
import RPi.GPIO as GPIO
from requests.auth import HTTPBasicAuth
from gpiozero import DigitalInputDevice

# Configuration constants
SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
SENSOR_GPIO_PIN = 4
POLLING_INTERVAL_SECONDS = 5

# Initialize the GPIO pin using gpiozero
sensor = DigitalInputDevice(SENSOR_GPIO_PIN, pull_up=False)

def read_sensor_value():
    """Read the value from the digital sensor."""
    return int(sensor.value)

def transmit_sensor_data(sensor_value):
    """Transmit the sensor data to the server."""
    data = {'sensor': 'digital_input', 'value': sensor_value}
    try:
        response = requests.post(SERVER_URL, json=data, auth=HTTPBasicAuth(USERNAME, PASSWORD))
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
    except requests.RequestException as e:
