    "write": "Writes data directly to the log file. Usage: 'write <data>'",
    "exit": "Exits the server. Usage: 'exit'"
}


def handle_command(command, command_args):
    """Processes user commands."""
    global server_running, log_file_path

    if not server_running:
        print("Server not running. Use 'start' to begin.")
        return

    try:
        if command == "start":
            if len(command_args) == 1:
                log_file_path = DEFAULT_LOG_FILE
            elif len(command_args) > 1:
                log_file_path = command_args[1]
