                print(f"Received and logged: {received_data}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            # Consider setting server_running to False in the exception handler
            # to stop the thread if critical errors occur.
        time.sleep(POLL_INTERVAL)


def print_help_all():
    """Prints help messages for all commands."""
    print("Available commands:")
    for command in help_messages:
        print(f"  {command}")
    print("Use 'help <command>' for more details.")


def main():
    """Main server loop."""
    print("Starting DOGServer...")
    try:
        while True:
            command = input("JAYES@ROVER53:\t")
            command_args = command.split()
            handle_command(command_args[0], command_args[1:])
    except KeyboardInterrupt:
        print("\nKeyboard interrupt received. Exiting.")
        server_running = False  # Ensure stop thread if it's running
        GPIO.cleanup()  # Clean up GPIO on exit
        sys.exit(0)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        server_running = False
        GPIO.cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

