# ambient_light_led_functional.py
# Reads ambient light from a TSL2561 sensor and controls LED brightness via PWM.
# Functional style for Raspberry Pi 5.

import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Constants
LED_GPIO_PIN = 18  # BCM numbering
TSL2561_I2C_ADDRESS = 0x39
PWM_FREQUENCY = 1000  # Hz
MAX_LUX = 1000.0
MIN_LUX = 0.0
INTEGRATION_TIME = 402  # ms
GAIN = "auto"


def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_light_sensor(i2c_bus):
    """Initializes the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_I2C_ADDRESS)
    except ValueError as e:
        print(f"Error initializing TSL2561: {e}")
        return None


def configure_sensor(sensor):
    """Configures the light sensor with integration time and gain."""
    try:
        sensor.integration_time = INTEGRATION_TIME
        sensor.gain = GAIN
        return sensor
    except Exception as e:
        print(f"Error configuring sensor: {e}")
        return None


def read_light_level(sensor):
    """Reads the light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None


def calculate_brightness(lux_value):
    """Calculates the LED brightness percentage based on lux value."""
    if lux_value is None:
        return 0.0
    try:
        return max(0.0, min(100.0, (lux_value / MAX_LUX) * 100.0))
    except Exception as e:
        print(f"Error calculating brightness: {e}")
        return 0.0


def set_led_brightness(pwm_instance, brightness_percentage):
    """Sets the LED brightness using PWM."""
    try:
        pwm_instance.ChangeDutyCycle(brightness_percentage)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")


def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return  # Exit if sensor initialization failed

    light_sensor = configure_sensor(light_sensor)
    if light_sensor is None:
        i2c_bus.deinit()
        return  # Exit if sensor configuration failed

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_GPIO_PIN, GPIO.OUT)
    pwm_led = GPIO.PWM(LED_GPIO_PIN, PWM_FREQUENCY)
    pwm_led.start(0)

    try:
        while True:
            lux = read_light_level(light_sensor)
            brightness = calculate_brightness(lux)

            print(f"Ambient Light: {lux:.2f} lux, LED Brightness: {brightness:.2f}%")
            set_led_brightness(pwm_led, brightness)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure cleanup on exit
        pwm_led.stop()
        GPIO.cleanup()
        i2c_bus.deinit()


if __name__ == "__main__":
    main()

