    import RPi.GPIO as GPIO
    led_available = True
except ImportError:
    print("RPi.GPIO not found, running without LED control.")
    led_available = False
except RuntimeError:
    print("Error: Could not initialize GPIO.  Are you running as root?")
    led_available = False


# Define the VADER sentiment lexicon (simplified)
vader_lexicon: Dict[str, float] = {
    "good": 1.0, "great": 1.0, "excellent": 1.0,
    "bad": -1.0, "terrible": -1.0, "awful": -1.0,
    "happy": 1.0, "sad": -1.0, "angry": -1.0,
    "love": 1.0, "hate": -1.0
}

# Define sentiment thresholds
POSITIVE_THRESHOLD: float = 0.2
NEGATIVE_THRESHOLD: float = -0.2


def tokenize_sentence(sentence: str) -> List[str]:
    """Tokenizes a sentence into lowercase words."""
    return sentence.lower().split()


def calculate_sentiment_score(sentence: str, lexicon: Dict[str, float]) -> float:
    """Calculates the average sentiment score for a sentence."""
    words = tokenize_sentence(sentence)
    total_score = 0.0
    word_count = 0

    for word in words:
        if word in lexicon:
            total_score += lexicon[word]
            word_count += 1
        else:
            total_score += 0.0  # Default score if word not found

    if word_count > 0:
        return total_score / word_count
    else:
        return 0.0  # Avoid division by zero


def classify_sentiment(score: float) -> str:
    """Classifies sentiment based on the score."""
    if score > POSITIVE_THRESHOLD:
        return "Positive"
    elif score < NEGATIVE_THRESHOLD:
        return "Negative"
    else:
        return "Neutral"


