# gpio_bit_transmit_receive_procedural.py
# A procedural style script for Raspberry Pi to send and receive data via GPIO bits.

import time
import signal
import sys
from gpiozero import OutputDevice, InputDevice

# Constants for GPIO pins (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for data transmission
START_SIGNAL = "0001"
END_SIGNAL = "0000"
BIT_DELAY = 0.0005

# Global flag for graceful exit
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful exit."""
    global running
    print("Exiting gracefully...")
    running = False

def initialize_gpio():
    """Initializes GPIO pins for output and input."""
    try:
        global data_out, timer_out, data_in, timer_in
        data_out = OutputDevice(DATA_OUT_PIN, initial_value=False)
        timer_out = OutputDevice(TIMER_OUT_PIN, initial_value=False)
        data_in = InputDevice(DATA_IN_PIN)
        timer_in = InputDevice(TIMER_IN_PIN)
        print("GPIO pins initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO pins: {e}")
        sys.exit(1)

def transmit_bit(bit):
    """Transmits a single bit."""
    try:
        data_out.on()
        timer_out.on()
        time.sleep(BIT_DELAY)
        data_out.off()
        time.sleep(BIT_DELAY)
        timer_out.off()
        time.sleep(BIT_DELAY)
    except Exception as e:
        print(f"Error transmitting bit: {e}")

def send_data(message):
    """Sends a string of data bit by bit."""
    try:
        print(f"Sending: {message}")
        for char in message:
            for bit in bin(ord(char))[2:].zfill(7):
                transmit_bit(bit)
        for _ in range(len(START_SIGNAL)):
            transmit_bit(START_SIGNAL[0])
        transmit_bit(False) # End signal
    except Exception as e:
        print(f"Error sending data: {e}")

def receive_bit():
    """Receives a single bit."""
    try:
        while timer_in.is_active():
            pass  # Wait for timer to go low
        return data_in.is_active()
    except Exception as e:
        print(f"Error receiving bit: {e}")
        return None

def receive_data():
    """Receives data bit by bit."""
    try:
        received_message = ""
        while running:
            received_byte = ""
            for _ in range(7):
                bit = receive_bit()
                if bit is None:
                    return None  # Indicate error
                received_byte += str(bit)

            if received_byte:
                received_message += chr(int(received_byte, 2))

            if receive_bit() is None:
                return None # Indicate error

            if received_message:
                print(f"Received: {received_message}")
                return received_message # Return after full message

    except Exception as e:
        print(f"Error receiving data: {e}")
        return None

def cleanup_gpio():
    """Releases GPIO resources."""
    try:
        data_out.close()
        timer_out.close()
        data_in.close()
        timer_in.close()
        print("GPIO pins released.")
    except Exception as e:
        print(f"Error cleaning up GPIO pins: {e}")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    if running:
        send_data("Hello")
    if running:
        received_message = receive_data()
        if received_message is None:
            print("Data reception failed.")

    cleanup_gpio()
    sys.exit(0)

