    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        return adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except ValueError as e:
        print(f"Error initializing fingerprint sensor (ValueError): {e}")
        return None
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor (RuntimeError): {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred during sensor initialization: {e}")
        return None

def acquire_fingerprint_image(sensor):
    """Acquires a fingerprint image from the sensor."""
    print('Waiting for finger...')
    while sensor.get_image() != adafruit_fingerprint.OK:
        pass
    return sensor.image_2_tz(1)

def search_fingerprint_database(sensor, template):
    """Searches the fingerprint database for a match."""
    try:
        return sensor.finger_search(template)
    except Exception as e:
        print(f"Error searching fingerprint database: {e}")
        return adafruit_fingerprint.NOFINGER

def authenticate_user(sensor, template):
    """Authenticates a user based on the fingerprint template."""
    match = search_fingerprint_database(sensor, template)
    if match == adafruit_fingerprint.NOFINGER:
        return False
    else:
        print(f'Access Granted')
        print(f'ID: {match}')
        print(f'Quality: {sensor.finger_print_2_tz(match)}')
        return True

def main():
    """Main function to run the fingerprint authentication."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            print('Place your finger on the sensor...')
            template = acquire_fingerprint_image(sensor)
            if template is None:
                continue  # Skip to the next iteration if image acquisition failed

            if authenticate_user(sensor, template):
                # User authenticated, perform actions here
                pass
            else:
                print('Access Denied')

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

