    pi = pigpio.pi()
    if not pi.connected:
        raise IOError("pigpio daemon not running")
    pi.set_mode(pin, pigpio.OUTPUT)
    pi.hardware_PWM(pin, frequency, 0)  # Start with 0 duty cycle
    return pi, pin

def read_light_level(sensor):
    """Reads the light level from the sensor in lux."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def map_light_to_brightness(light_level, gain=10):
    """Maps the light level to a brightness percentage (0-100)."""
    if light_level is None:
        return 0
    return min(100, max(0, int(light_level / gain)))

def set_led_brightness(pi, pin, brightness):
    """Sets the LED brightness using hardware PWM."""
    try:
        pi.hardware_PWM(pin, PWM_FREQUENCY, brightness)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def clamp(value, min_val, max_val):
    """Clamps the value within the specified range."""
    return max(min_val, min(value, max_val))

def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return

    pi, led_pin = initialize_pwm(LED_GPIO_PIN, PWM_FREQUENCY)

    try:
        while True:
            light_level = read_light_level(light_sensor)
            brightness = map_light_to_brightness(light_level)
            set_led_brightness(pi, led_pin, clamp(brightness, 0, 100))
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        pi.hardware_PWM(led_pin, PWM_FREQUENCY, 0) # Turn off PWM
        pi.stop()
        i2c_bus.deinit()
        print("GPIO and I2C cleaned up")

if __name__ == "__main__":
    main()

