from gpiozero import PWMOutputDevice, exc
from functools import partial
from typing import Callable, Union

# Constants for PWM frequency and GPIO pin
PWM_FREQUENCY = 25000  # Hz (standard for 4-wire PWM fans)
FAN_GPIO_PIN = 12  # BCM numbering

# Error handling function
def handle_error(message: str) -> None:
    """Handles errors by printing a message and exiting."""
    print(f"Error: {message}")
    exit(1)

# Type alias for PWM duty cycle function
DutyCycleFunction = Callable[[float], None]

def create_fan(pin: int, frequency: int = PWM_FREQUENCY) -> PWMOutputDevice:
    """Creates and initializes a PWM fan object, handling potential errors."""
    try:
        fan = PWMOutputDevice(pin, frequency=frequency)
        fan.value = 0  # Start with fan off
        return fan
    except exc.GPIODeviceError as e:
        handle_error(f"Failed to initialize PWM on GPIO {pin}: {e}")

def get_fan_speed_input() -> Union[float, None]:
    """Prompts the user for a fan speed (0-100) and handles invalid input."""
    while True:
        try:
            speed = float(input("Enter fan speed (0-100): "))
            if 0 <= speed <= 100:
                return speed
            else:
                print("Invalid input. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number.")
        except KeyboardInterrupt:
            print("\nOperation cancelled by user.")
            return None

def control_fan_speed(fan: PWMOutputDevice, set_speed: DutyCycleFunction) -> None:
    """Continuously controls the fan speed based on user input."""
    try:
        while True:
            speed = get_fan_speed_input()
            if speed is None:
                break  # Exit loop if user cancelled

            set_speed(speed)  # Set the fan speed
            print(f"Fan speed set to {speed}%")

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        stop_fan(fan)


def stop_fan(fan: PWMOutputDevice) -> None:
    """Stops the fan and releases resources."""
    try:
        fan.value = 0  # Stop the fan
        fan.close()  # Release GPIO resources
        print("Fan stopped and GPIO resources released.")
    except Exception as e:
        print(f"Error stopping fan: {e}")


def main() -> None:
    """Main function to run the fan control program."""
    try:
        fan = create_fan(FAN_GPIO_PIN)
        set_speed = partial(fan.value, relax=False) # Create partial function for setting speed immediately
        control_fan_speed(fan, set_speed)

    except Exception as e:
        handle_error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure fan is stopped and resources released even if create_fan fails
        stopped_fan = None # Initialize to None for clarity
        if 'fan' in locals() and not isinstance(fan, PWMOutputDevice): # Check if fan was created but is not a PWMOutputDevice (error occurred)
            handle_error("Fan initialization failed. GPIO may be in an undefined state.")
        elif 'fan' in locals(): # If fan was created successfully
            stopped_fan = fan
        elif 'fan' in locals() and isinstance(fan, PWMOutputDevice): # If fan was created but has issues
            handle_error("Fan initialization failed. GPIO may be in an undefined state.")
        else:
            handle_error("Fan object could not be created.")

        if stopped_fan:
            stop_fan(stopped_fan)


if __name__ == "__main__":
    main()

