# hydroponics_control_intent.py
# Raspberry Pi script to parse text into hydroponics control intents

import time
import logging
from gpiozero import OutputDevice

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins for actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize actuators using gpiozero OutputDevice
try:
    nutrient_pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    grow_light = OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
except Exception as e:
    logging.error(f"Failed to initialize actuators: {e}")
    exit(1)

def parse_intent(phrase):
    """Parses a phrase into a hydroponics control intent."""
    phrase = phrase.lower()
    if "turn the pump on" in phrase:
        return "pump_on"
    elif "turn pump off" in phrase:
        return "pump_off"
    elif "switch the light" in phrase:
        return "light_toggle"
    else:
        return None

def apply_intent(intent):
    """Applies a parsed intent to the actuators."""
    if intent == "pump_on":
        logging.info("Turning nutrient pump ON")
        nutrient_pump.on()
    elif intent == "pump_off":
        logging.info("Turning nutrient pump OFF")
        nutrient_pump.off()
    elif intent == "light_toggle":
        logging.info("Toggling grow light")
        grow_light.toggle()
    else:
        logging.warning(f"Unknown intent: {intent}")

def main():
    """Main function to process phrases and control actuators."""
    phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    try:
        for phrase in phrases:
            intent = parse_intent(phrase)
            if intent:
                apply_intent(intent)
                logging.info(f"Parsed phrase: {phrase} - Intent: {intent}")
            else:
                logging.warning(f"Parsed phrase: {phrase} - Intent: unknown")
            time.sleep(1)  # Simulate delay between commands
    except KeyboardInterrupt:
        logging.info("Script interrupted by user. Shutting down...")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        # Ensure actuators are off on exit
        nutrient_pump.off()
        grow_light.off()
        logging.info("Actuators shut down. Exiting.")

if __name__ == "__main__":
    main()

