import smbus2 as smbus
import contextlib

def _probe_device(address, bus_number=1, retries=3):
    """Probes the I2C bus to verify device presence."""
    for _ in range(retries):
        try:
            with contextlib.closing(smbus.SMBus(bus_number)) as bus:
                bus.write_byte(address, 0x12)  # Send a test byte
                if bus.read_byte(address) == 0x12: # Read the same byte back
                    return True
        except (IOError, OSError):
            pass  # Ignore errors during probe
    return False

def _get_smbus_class(bus_number=1):
    """Returns the SMBus class based on Raspberry Pi revision."""
    if bus_number == 1:
        return smbus
    else:
        return smbus2

def _with_smbus(bus_number=1, action):
    """Context manager for I2C bus."""
    smbus_class = _get_smbus_class(bus_number)
    try:
        with contextlib.closing(smbus_class(bus_number)) as bus:
            return action(bus)
    except (IOError, OSError) as e:
        raise RuntimeError(f"I2C communication error: {e}")

class I2CDevice:
    """A simple I2C device wrapper for Raspberry Pi."""

    def __init__(self, address, bus_number=1):
        """Initializes the I2C device."""
        if not _probe_device(address, bus_number):
            raise RuntimeError(f"Device at address 0x{address:02X} not found.")

        self.address = address
        self.bus_number = bus_number

    def write_byte(self, register, value):
        """Writes a byte to a register."""
        def _action(bus):
            bus.write_byte_data(self.address, register, value)
        _with_smbus(self.bus_number, _action)

    def read_byte(self, register):
        """Reads a byte from a register."""
