import smbus2 as smbus
from datetime import datetime, timedelta
import logging
import os

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_ADDRESS = 0x68
DS1339_ADDRESS = 0x69
DEFAULT_I2C_BUS = 1
CENTURY = 21

# Register Addresses (DS1338)
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
REG_STATUS = 0x0F  # Added Status Register address

# Register Masks and Values (DS1338)
MASK_4_BIT = 0x0F
MASK_3_BIT = 0x7F
RESUME_MASK = 0x80
OSF_MASK = 0x40
RFU_MASK = 0x03

# Century Values
THIS_CENTURY = CENTURY
LAST_CENTURY = CENTURY - 1


class DS1338Error(Exception):
    """Base class for DS1338-specific exceptions."""
    pass


class DS1338InitializationError(DS1338Error):
    """Raised when the DS1338 chip fails to initialize."""
    pass


class DS1338CommunicationError(DS1338Error):
    """Raised when there is an I2C communication error."""
    pass


def _validate_time_component(value, component_name, minimum=None, maximum=None):
    """Validates that a time component falls within the expected range."""
    if minimum is not None and value < minimum:
        raise ValueError(f"{component_name} must be greater than or equal to {minimum}")
    if maximum is not None and value > maximum:
        raise ValueError(f"{component_name} must be less than or equal to {maximum}")


def _bcd_to_int(bcd_value):
    """Converts a 2x4bit BCD to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        raise DS1338Error("Invalid BCD value provided")


def _int_to_bcd(integer_value):
    """Converts an integer to BCD format."""
    if not 0 <= integer_value <= 99:
        raise DS1338Error("Integer value must be between 0 and 99 for BCD conversion.")
    return (integer_value // 10 << 4) | (integer_value % 10)


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, twi=DEFAULT_I2C_BUS, address=DS1338_ADDRESS):
        """Initializes the DS1338 RTC driver."""
        self._bus = smbus.SMBus(twi)
        self._address = address
        self._century = THIS_CENTURY
        self._last_second = None

        try:
            # Verify device presence by reading a register.  If the chip is not
            # responding, attempt to re-initialize the I2C bus.
            self._read_register(REG_STATUS)
            logger.info("DS1338 initialized successfully.")
        except (IOError, OSError) as e:
            raise DS1338InitializationError(f"Failed to initialize DS1338 at address 0x{address:02X}: {e}")

    def _write_register(self, register, data):
        """Writes a byte of data to a specific register on the DS1338."""
        try:
            self._bus.write_byte_data(self._address, register, data)
        except (IOError, OSError) as e:
            raise DS1338CommunicationError(f"I2C write error: {e}")

    def _read_register(self, register):
        """Reads a byte of data from a specific register on the DS1338."""
        try:
            return self._bus.read_byte_data(self._address, register)
        except (IOError, OSError) as e:
            raise DS1338CommunicationError(f"I2C read error: {e}")


    def _read_time_register(self, register):
        """Reads and converts a time register value (BCD) to an integer."""
        return _bcd_to_int(self._read_register(register))

    def _read_seconds(self):
        """Reads the seconds value."""
        return self._read_time_register(REG_SECONDS)

    def _read_minutes(self):
        """Reads the minutes value."""
        return self._read_time_register(REG_MINUTES)

    def _read_hours(self):
        """Reads the hours value (24-hour format)."""
        hours_data = self._read_register(REG_HOURS)
        return _bcd_to_int(hours_data & MASK_3_BIT)

    def _read_day(self):
        """Reads the day of the week."""
        return self._read_time_register(REG_DAY)

    def _read_date(self):
        """Reads the date."""
        return self._read_time_register(REG_DATE)

    def _read_month(self):
        """Reads the month."""
        return self._read_time_register(REG_MONTH)

    def _read_year(self):
        """Reads the year."""
        return _bcd_to_int(self._read_register(REG_YEAR))


    def _read_all(self):
        """Reads all time and date components."""
        try:
            year = self._read_year()
            month = self._read_month()
            date = self._read_date()
            day = self._read_day()
            hours = self._read_hours()
            minutes = self._read_minutes()
            seconds = self._read_seconds()
            return year, month, date, day, hours, minutes, seconds
        except DS1338CommunicationError as e:
            raise DS1338Error(f"Error reading all RTC data: {e}")


    def read_datetime(self, century=THIS_CENTURY):
        """Reads the date and time from the RTC and returns a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self._read_all()
            timestamp = datetime.now().replace(year=century * 100 + year,
                                               month=month,
                                               day=date,
                                               hour=hours,
                                               minute=minutes,
                                               second=seconds,
                                               microsecond=0)
            return timestamp
        except ValueError as e:  # Catch invalid date/time values
            raise DS1338Error(f"Invalid date/time data read from RTC: {e}")
        except DS1338Error as e:
            raise


    def read_time(self):
        """Reads the time from the RTC and returns a datetime object referencing the current date."""
        try:
            now = datetime.now()
            year = self._read_year()
            month = self._read_month()
            date = self._read_date()
            timestamp = now.replace(year=century * 100 + year,
                                    month=month,
                                    day=date,
                                    hour=self._read_hours(),
                                    minute=self._read_minutes(),
                                    second=self._read_seconds(),
                                    microsecond=0)
            return timestamp
        except ValueError as e:
            raise DS1338Error(f"Invalid time data read from RTC: {e}")
        except DS1338Error as e:
            raise


    def _update_time_register(self, register, value):
        """Updates a time register value (BCD)."""
        try:
            self._write_register(register, _int_to_bcd(value))
        except DS1338CommunicationError as e:
            raise


    def _update_seconds(self, seconds):
        """Updates the seconds value and handles the rollover to minutes."""
        try:
            if 0 <= seconds <= 59:
                self._update_time_register(REG_SECONDS, seconds)
                self._last_second = seconds
            else:
                raise ValueError("Seconds must be between 0 and 59")
        except ValueError as e:
            raise DS1338Error(f"Invalid seconds value: {e}")


    def _update_minutes(self, minutes):
        """Updates the minutes value and handles the rollover to hours."""
        try:
            if 0 <= minutes <= 59:
                self._update_time_register(REG_MINUTES, minutes)
                self._last_second = None  # Reset last second value
            else:
                raise ValueError("Minutes must be between 0 and 59")
        except ValueError as e:
            raise DS1338Error(f"Invalid minutes value: {e}")


    def _update_hours(self, hours):
        """Updates the hours value (24-hour format)."""
        try:
            if 0 <= hours <= 23:
                self._update_time_register(REG_HOURS, _int_to_bcd(hours))
            else:
                raise ValueError("Hours must be between 0 and 23")
        except ValueError as e:
            raise DS1338Error(f"Invalid hours value: {e}")


    def _update_day(self, day):
        """Updates the day of the week."""
        try:
            if 1 <= day <= 7:
                self._update_time_register(REG_DAY, _int_to_bcd(day))
            else:
                raise ValueError("Day must be between 1 and 7")
        except ValueError as e:
            raise DS1338Error(f"Invalid day value: {e}")


    def _update_date(self, date):
        """Updates the date."""
        try:
            if 1 <= date <= 31:
                self._update_time_register(REG_DATE, _int_to_bcd(date))
            else:
                raise ValueError("Date must be between 1 and 31")
        except ValueError as e:
            raise DS1338Error(f"Invalid date value: {e}")


    def _update_month(self, month):
        """Updates the month."""
        try:
            if 1 <= month <= 12:
                self._update_time_register(REG_MONTH, _int_to_bcd(month))
            else:
                raise ValueError("Month must be between 1 and 12")
        except ValueError as e:
            raise DS1338Error(f"Invalid month value: {e}")


    def _update_year(self, year):
        """Updates the year."""
        try:
            if (THIS_CENTURY * 100 + year) - (THIS_CENTURY * 100 + LAST_CENTURY) <= 99:
                self._update_time_register(REG_YEAR, _int_to_bcd(year))
            else:
                raise ValueError("Year must be within this century")
        except ValueError as e:
            raise DS1338Error(f"Invalid year value: {e}")


    def write_datetime(self, dt):
        """Writes the given datetime object to the RTC."""
        try:
            self._update_year(dt.year % 100)
            self._update_month(dt.month)
            self._update_date(dt.day)
            self._update_hours(dt.hour)
            self._update_minutes(dt.minute)
            self._update_seconds(dt.second)
        except DS1338Error as e:
            raise

    def write_time(self, t):
        """Writes the given time object to the RTC."""
        try:
            self._update_hours(t.hour)
            self._update_minutes(t.minute)
            self._update_seconds(t.second)
        except DS1338Error as e:
            raise


    def _check_oscillator(self):
        """Checks the oscillator status."""
        status = self._read_register(REG_STATUS)
        return (status & OSF_MASK) == 0


    def _resume_operation(self):
        """Resumes operation after an OSF interrupt."""
        try:
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) | RESUME_MASK)
        except DS1338CommunicationError as e:
            raise


    def get_last_second(self):
        """Returns the last second value read."""
        return self._last_second


    def set_watchdog (self, enable=True, resume=True):
        """Enables or disables the watchdog (OSF interrupt)."""
        try:
            status = self._read_register(REG_CONTROL)
            new_control = status & ~RFU_MASK
            if enable:
                new_control |= RESUME_MASK | OSF_MASK if resume else RESUME_MASK
            else:
                new_control &= ~RESUME_MASK
            self._write_register(REG_CONTROL, new_control)
        except DS1338CommunicationError as e:
            raise


    def clear_watchdog (self):
        """Clears the watchdog interrupt."""
        try:
            self._write_register(REG_STATUS, self._read_register(REG_STATUS) & ~OSF_MASK)
        except DS1338CommunicationError as e:
            raise


    def is_oscillator_failed (self):
        """Checks if the oscillator has failed."""
        return (self._read_register(REG_STATUS) & OSF_MASK) != 0


    def _disable_oscillator(self):
        """Disables the oscillator."""
        try:
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) & ~RESUME_MASK)
        except DS1338CommunicationError as e:
            raise


    def sleep(self):
        """Stops the oscillator and enters sleep mode."""
        try:
            self._disable_oscillator()
            # Set the CH bit in the Control register to enter sleep mode.
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) | 0x80)
        except DS1338CommunicationError as e:
            raise


    def wake_up(self):
        """Wakes up the RTC after sleep mode."""
        try:
            # Clear the CH bit in the Control register to wake up.
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) & ~0x80)
        except DS1338CommunicationError as e:
            raise


def main():
    """Main function to demonstrate DS1338 usage."""
    try:
        rtc = DS1338()
        now = datetime.now()
        rtc.write_datetime(now)
        logger.info(f"RTC time set to: {now}")
    except DS1338Error as e:
        logger.error(f"DS1338 operation failed: {e}")


if __name__ == "__main__":
    main()

