            self._update_minutes(t.minute)
            self._update_seconds(t.second)
        except DS1338Error as e:
            raise


    def _check_oscillator(self):
        """Checks the oscillator status."""
        status = self._read_register(REG_STATUS)
        return (status & OSF_MASK) == 0


    def _resume_operation(self):
        """Resumes operation after an OSF interrupt."""
        try:
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) | RESUME_MASK)
        except DS1338CommunicationError as e:
            raise


    def get_last_second(self):
        """Returns the last second value read."""
        return self._last_second


    def set_watchdog (self, enable=True, resume=True):
        """Enables or disables the watchdog (OSF interrupt)."""
        try:
            status = self._read_register(REG_CONTROL)
            new_control = status & ~RFU_MASK
            if enable:
                new_control |= RESUME_MASK | OSF_MASK if resume else RESUME_MASK
            else:
                new_control &= ~RESUME_MASK
            self._write_register(REG_CONTROL, new_control)
        except DS1338CommunicationError as e:
            raise


    def clear_watchdog (self):
        """Clears the watchdog interrupt."""
        try:
            self._write_register(REG_STATUS, self._read_register(REG_STATUS) & ~OSF_MASK)
        except DS1338CommunicationError as e:
            raise


    def is_oscillator_failed (self):
        """Checks if the oscillator has failed."""
        return (self._read_register(REG_STATUS) & OSF_MASK) != 0


    def _disable_oscillator(self):
        """Disables the oscillator."""
        try:
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) & ~RESUME_MASK)
        except DS1338CommunicationError as e:
            raise


    def sleep(self):
        """Stops the oscillator and enters sleep mode."""
        try:
            self._disable_oscillator()
            # Set the CH bit in the Control register to enter sleep mode.
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) | 0x80)
        except DS1338CommunicationError as e:
            raise


    def wake_up(self):
        """Wakes up the RTC after sleep mode."""
        try:
            # Clear the CH bit in the Control register to wake up.
            self._write_register(REG_CONTROL, self._read_register(REG_CONTROL) & ~0x80)
        except DS1338CommunicationError as e:
            raise


def main():
    """Main function to demonstrate DS1338 usage."""
    try:
        rtc = DS1338()
        now = datetime.now()
        rtc.write_datetime(now)
        logger.info(f"RTC time set to: {now}")
    except DS1338Error as e:
        logger.error(f"DS1338 operation failed: {e}")


