from datetime import datetime, timezone
import contextlib

# Constants for I2C and DS1338
DEFAULT_I2C_BUS = 1
DEFAULT_I2C_ADDRESS = 0x68
DS1338_REG_SECONDS = 0x00
DS1338_REG_MINUTES = 0x01
DS1338_REG_HOURS = 0x02
DS1338_REG_DAY = 0x03
DS1338_REG_DATE = 0x04
DS1338_REG_MONTH = 0x05
DS1338_REG_YEAR = 0x06
DS1338_REG_CONTROL = 0x07

def _bcd_to_int(bcd):
    """Decode a 2x4bit BCD value to an integer."""
    try:
        return int(f"{bcd >> 4:01}{bcd & 0x0F:01}")
    except ValueError:
        raise ValueError("Invalid BCD value")


def _int_to_bcd(n):
    """Encode an integer to BCD format."""
    try:
        tens, units = divmod(n, 10)
        return (tens << 4) | units
    except TypeError:
        raise ValueError("Invalid integer value")


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, i2c_address=DEFAULT_I2C_ADDRESS):
        """Initialize the DS1338 driver."""
        try:
             with contextlib.closing(smbus.SMBus(i2c_bus)) as self.bus:  # Use context manager for bus closing
                self._address = i2c_address
                # Initialize the RTC (clear CH bit)
                self.bus.write_byte_data(self._address, DS1338_REG_CONTROL, 0x00)
        except Exception as e:
            raise IOError(f"Failed to initialize DS1338 at address 0x{i2c_address:02X}: {e}")

    def _read_register(self, register):
        """Read a byte from the specified register."""
        try:
            with contextlib.closing(smbus.SMBus(DEFAULT_I2C_BUS)) as bus: # Reopen bus as it might be closed
                return bus.read_byte_data(self._address, register)
        except Exception as e:
            raise IOError(f"Failed to read register 0x{register:02X}: {e}")

    def _write_register(self, register, value):
        """Write a byte to the specified register."""
        try:
            with contextlib.closing(smbus.SMBus(DEFAULT_I2C_BUS)) as bus:  # Reopen bus as it might be closed
                bus.write_byte_data(self._address, register, value)
        except Exception as e:
            raise IOError(f"Failed to write to register 0x{register:02X}: {e}")

    def read_all(self):
        """Read all date/time registers and return as a tuple."""
        year = _bcd_to_int(self._read_register(DS1338_REG_YEAR))
        month = _bcd_to_int(self._read_register(DS1338_REG_MONTH))
        date = _bcd_to_int(self._read_register(DS1338_REG_DATE))
        day = _bcd_to_int(self._read_register(DS1338_REG_DAY))
        hours = _bcd_to_int(self._read_register(DS1338_REG_HOURS) & 0x3F) # Ensure 24-hour format
        minutes = _bcd_to_int(self._read_register(DS1338_REG_MINUTES))
        seconds = _bcd_to_int(self._read_register(DS1338_REG_SECONDS) & 0x7F) # Clear CH bit
        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        """Return the current time as a datetime object with timezone.utc."""
        year, month, date, _, hours, minutes, seconds = self.read_all()
        return datetime(year=2000 + year, month=month, day=date, hour=hours, minute=minutes, second=seconds,
                        tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all date/time registers."""

        if not all(0 <= val <= limit for val, limit in [(seconds, 7), (minutes, 59), (hours, 23),
                                                      (day, 7), (date, 31), (month, 12), (year, 99)]):
            raise ValueError("Date/time values out of range")

        self._write_register(DS1338_REG_SECONDS, _int_to_bcd(seconds))
        self._write_register(DS1338_REG_MINUTES, _int_to_bcd(minutes))
        self._write_register(DS1338_REG_HOURS, _int_to_bcd(hours)) # Ensure 24-hour format
        self._write_register(DS1338_REG_DAY, _int_to_bcd(day))
        self._write_register(DS1338_REG_DATE, _int_to_bcd(date))
        self._write_register(DS1338_REG_MONTH, _int_to_bcd(month))
        self._write_register(DS1338_REG_YEAR, _int_to_bcd(year % 100)) # Year in the century


    def write_datetime(self, dt):
        """Write the current time from a datetime object."""
        self.write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(),
                       dt.hour, dt.minute, dt.second)

    def write_now(self):
        """Set the RTC to the current time."""

        self.write_datetime(datetime.now(timezone.utc))


if __name__ == "__main__":
    rtc = None
    try:
        rtc = DS1338()
        print(rtc.read_datetime().isoformat())
    except IOError as e:
        print(f"Error: {e}")
    finally:
        if rtc is not None:
            try:
                rtc.close()  # Assuming close method is implemented
            except AttributeError:
                pass # DS1338 doesn't have a close method
            except Exception as e:
                print(f"Error closing DS1338: {e}")

