import serial
import time


def parse_gprmc(nmea_data):
    """
    Parses a GPRMC NMEA sentence to extract latitude, longitude, and validate the fix.
    Returns a tuple of (latitude, longitude, fix_valid) or None if parsing fails.
    """
    try:
        if not nmea_data.startswith("$GPRMC"):
            return None

        sdata = nmea_data.split(",")
        if sdata[2] == 'V':
            return None

        latitude = decode_coordinate(sdata[3])  # Latitude
        latitude_direction = sdata[4]  # Latitude direction (N/S)
        longitude = decode_coordinate(sdata[5])  # Longitude
        longitude_direction = sdata[6]  # Longitude direction (E/W)

        print(f"Latitude: {latitude} ({latitude_direction}), Longitude: {longitude} ({longitude_direction})")

        return latitude, longitude, True

    except (IndexError, ValueError) as e:
        print(f"Error parsing GPRMC sentence: {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None


def decode_coordinate(coordinate):
    """
    Converts GPS coordinate from ddmm.mmmm format to decimal degrees.
    """
    try:
        parts = coordinate.split(".")
        degrees = parts[0]
        minutes = parts[1]
        decimal_minutes = parts[2]
        decimal_degrees = float(degrees) + (float(minutes) + float(decimal_minutes) / 60) / 60
        return decimal_degrees
    except (ValueError, IndexError) as e:
        print(f"Error decoding coordinate: {e}")
        return None


def main():
    """
    Main function to initialize serial communication with the GPS module and read/parse data.
    """
    print("Receiving GPS data...")

    try:
        ser = serial.Serial("/dev/serial0", baudrate=9600, timeout=1)
        while True:
            try:
                nmea_data = ser.readline().decode('utf-8').strip()
                if nmea_data:
                    parse_gprmc(nmea_data)
                time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                break
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    finally:
        try:
            if 'ser' in locals() and ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")


if __name__ == "__main__":
    main()

