import json
import time
import socket
import threading
import traceback
import logging
from typing import List, Dict, Any, Union
from flask import Flask, Response, request, jsonify, abort
import serial
import os

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)

# In-memory data store (replace with database in a real application)
data_store: List[Dict[str, Any]] = []
data_lock = threading.Lock()

class SerialCommunicator:
    """
    Manages serial communication with the instrument.
    """
    def __init__(self, port: str, baudrate: int = 9600, timeout: float = 1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self.lock = threading.Lock()

    def open(self):
        """Opens the serial port."""
        try:
            with self.lock:
                if self.ser is None:
                    self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
                    logging.info(f"Opened serial port {self.port} at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port}: {e}")
            raise

    def send(self, command: str):
        """Sends a command to the instrument."""
        try:
            with self.lock:
                if self.ser and self.ser.is_open:
                    self.ser.write(command.encode())
                    # Basic verification (can be improved)
                    response = self.receive_line()
                    if response is None or not response.startswith(command):
                        logging.warning(f"Unexpected response from instrument: {response}")
        except serial.SerialException as e:
            logging.error(f"Error sending command to serial port {self.port}: {e}")
            raise

    def receive_line(self) -> Union[str, None]:
        """Receives a line from the instrument."""
        try:
            with self.lock:
                if self.ser and self.ser.is_open:
                    response = self.ser.readline().decode().strip()
                    return response if response else None
        except serial.SerialException as e:
            logging.error(f"Error receiving data from serial port {self.port}: {e}")
            return None
        except Exception as e:
            logging.error(f"Error reading from serial port {self.port}: {e}")
            return None

    def close(self):
        """Closes the serial port (idempotent)."""
        with self.lock:
            if self.ser and self.ser.is_open:
                self.ser.close()
                logging.info(f"Closed serial port {self.port}.")

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()


def get_serial_communicator() -> SerialCommunicator:
    """Returns a SerialCommunicator instance."""
    return SerialCommunicator(port=os.environ.get("INSTRUMENT_PORT", "/dev/ttyUSB0"), baudrate=int(os.environ.get("INSTRUMENT_BAUDRATE", "9600")), timeout=float(os.environ.get("INSTRUMENT_TIMEOUT", "1"))))


def get_data_store() -> List[Dict[str, Any]]:
    """Returns a copy of the data store."""
    with data_lock:
        return data_store[:]  # Return a copy


def update_data_store(item: Dict[str, Any]) -> None:
    """Updates the data store."""
    with data_lock:
        data_store.append(item)


@app.route('/version', methods=['GET'])
def get_version() -> Response:
    """Retrieves the instrument version via serial."""
    try:
        with get_serial_communicator() as communicator:
            communicator.send("*IDN?\n")
            response = communicator.receive_line()
            if response:
                return Response(response + "\n", mimetype='text/plain')
            else:
                return Response("No response received from instrument.\n", mimetype='text/plain', status=504)
    except serial.SerialException:
        return Response("Failed to open serial port.\n", mimetype='text/plain', status=500)
    except Exception as e:
        logging.error(f"Error getting version: {e}")
        return Response(f"An error occurred: {e}\n", mimetype='text/plain', status=500)


@app.route('/data', methods=['GET'])
def get_all_data() -> Response:
    """Retrieves all data."""
    data = get_data_store()
    if not data:
        abort(404)
    return jsonify(data)


@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id: int) -> Response:
    """Retrieves a specific data item."""
    data = get_data_store()
    item = next((item for item in data if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)


@app.route('/data', methods=['POST'])
def create_data_item() -> Response:
    """Creates a new data item."""
    try:
        new_item = request.get_json()
        if not new_item:
            abort(400, "Invalid JSON data")

        # Basic validation
        if not isinstance(new_item.get("name"), str) or not new_item.get("name"):
            abort(400, "Name is required and must be a string")
        if not isinstance(new_item.get("done"), bool):
            abort(400, "Done must be a boolean")

        new_item["id"] = (get_data_store(),)[0]['id'] + 1 if get_data_store() else 1 # Auto-increment ID
        update_data_store(new_item)
        return jsonify(new_item), 201

    except ValueError as e:
        abort(400, f"Invalid data: {e}")
    except Exception as e:
        logging.error(f"Error creating data item: {e}")
        abort(500)


def cleanup(signum: int, frame) -> None:
    """Cleans up resources on exit."""
    logging.info("Shutting down...")
    try:
        with get_serial_communicator() as communicator:
            communicator.close()
    except Exception as e:
        logging.error(f"Error during shutdown: {e}")
    exit(0)


if __name__ == '__main__':
    # Start the serial server in a separate thread (not implemented here, but required)
    # For example, you could have a serial_server.py that listens for commands and controls the instrument.
    # You would then need to start that server separately, e.g., `python serial_server.py &`

    # Register signals for graceful shutdown
    import signal
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Run the Flask app
    app.run(debug=False, host='0.0.0.0')

