        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self.lock = threading.Lock()

    def open(self):
        """Opens the serial port."""
        try:
            with self.lock:
                if self.ser is None:
                    self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
                    logging.info(f"Opened serial port {self.port} at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port}: {e}")
            raise

    def send(self, command: str):
        """Sends a command to the instrument."""
        try:
            with self.lock:
                if self.ser and self.ser.is_open:
                    self.ser.write(command.encode())
                    # Basic verification (can be improved)
                    response = self.receive_line()
                    if response is None or not response.startswith(command):
                        logging.warning(f"Unexpected response from instrument: {response}")
        except serial.SerialException as e:
            logging.error(f"Error sending command to serial port {self.port}: {e}")
            raise

    def receive_line(self) -> Union[str, None]:
        """Receives a line from the instrument."""
        try:
            with self.lock:
                if self.ser and self.ser.is_open:
                    response = self.ser.readline().decode().strip()
                    return response if response else None
        except serial.SerialException as e:
            logging.error(f"Error receiving data from serial port {self.port}: {e}")
            return None
        except Exception as e:
            logging.error(f"Error reading from serial port {self.port}: {e}")
            return None

    def close(self):
        """Closes the serial port (idempotent)."""
        with self.lock:
            if self.ser and self.ser.is_open:
                self.ser.close()
                logging.info(f"Closed serial port {self.port}.")

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()


def get_serial_communicator() -> SerialCommunicator:
    """Returns a SerialCommunicator instance."""
    return SerialCommunicator(port=os.environ.get("INSTRUMENT_PORT", "/dev/ttyUSB0"), baudrate=int(os.environ.get("INSTRUMENT_BAUDRATE", "9600")), timeout=float(os.environ.get("INSTRUMENT_TIMEOUT", "1"))))


