    """Retrieves the instrument version via serial."""
    try:
        with get_serial_communicator() as communicator:
            communicator.send("*IDN?\n")
            response = communicator.receive_line()
            if response:
                return Response(response + "\n", mimetype='text/plain')
            else:
                return Response("No response received from instrument.\n", mimetype='text/plain', status=504)
    except serial.SerialException:
        return Response("Failed to open serial port.\n", mimetype='text/plain', status=500)
    except Exception as e:
